I'm building a graph library and have a working Dijkstra implementation. I want to extend it to also track and return the actual shortest path (list of nodes), not just the distance. Here's what I have, and here are the new tests I need to pass:

```python
from typing import Dict, List, Optional, Tuple
import heapq

Graph = Dict[str, Dict[str, float]]

def dijkstra(
    graph: Graph,
    source: str,
    target: str,
) -> Tuple[float, List[str]]:
    """Find shortest path from source to target using Dijkstra's algorithm.

    Args:
        graph: Adjacency dict {node: {neighbor: weight}}
        source: Starting node
        target: Destination node

    Returns:
        Tuple of (total_distance, path_as_list_of_nodes)
        Returns (float('inf'), []) if no path exists.
    """
    pass


# --- Existing tests (all pass with previous implementation that returned only distance) ---
# Updated signatures to match new return type

def test_simple_path():
    g = {
        "A": {"B": 1.0, "C": 4.0},
        "B": {"C": 2.0, "D": 5.0},
        "C": {"D": 1.0},
        "D": {}
    }
    dist, path = dijkstra(g, "A", "D")
    assert dist == 4.0
    assert path == ["A", "B", "C", "D"]

def test_direct_edge():
    g = {
        "X": {"Y": 7.0},
        "Y": {}
    }
    dist, path = dijkstra(g, "X", "Y")
    assert dist == 7.0
    assert path == ["X", "Y"]

def test_no_path():
    g = {
        "A": {"B": 1.0},
        "B": {},
        "C": {"D": 1.0},
        "D": {}
    }
    dist, path = dijkstra(g, "A", "C")
    assert dist == float('inf')
    assert path == []

def test_source_equals_target():
    g = {"A": {"B": 5.0}, "B": {}}
    dist, path = dijkstra(g, "A", "A")
    assert dist == 0.0
    assert path == ["A"]

def test_multiple_paths_picks_shortest():
    g = {
        "S": {"A": 10.0, "B": 3.0},
        "A": {"T": 2.0},
        "B": {"A": 4.0, "T": 15.0},
        "T": {}
    }
    dist, path = dijkstra(g, "S", "T")
    assert dist == 9.0
    assert path == ["S", "B", "A", "T"]

# --- New tests for tie-breaking and path reconstruction ---

def test_equal_cost_paths_returns_lexicographic():
    # Two paths of equal cost: S->A->T (cost 5+5=10) and S->B->T (cost 3+7=10)
    # Should return lexicographically smaller path
    g = {
        "S": {"A": 5.0, "B": 3.0},
        "A": {"T": 5.0},
        "B": {"T": 7.0},
        "T": {}
    }
    dist, path = dijkstra(g, "S", "T")
    assert dist == 10.0
    assert path == ["S", "A", "T"]  # lexicographically first

def test_large_graph_correctness():
    g = {
        "A": {"B": 2.0, "C": 6.0},
        "B": {"D": 3.0, "E": 8.0},
        "C": {"E": 2.0},
        "D": {"F": 1.0},
        "E": {"F": 4.0},
        "F": {}
    }
    dist, path = dijkstra(g, "A", "F")
    assert dist == 6.0
    assert path == ["A", "B", "D", "F"]

def test_path_reconstruction_with_negative_lookalike():
    # All weights positive, but path costs are close
    g = {
        "P": {"Q": 1.0, "R": 4.0},
        "Q": {"R": 2.0, "S": 6.0},
        "R": {"S": 1.0},
        "S": {}
    }
    dist, path = dijkstra(g, "P", "S")
    assert dist == 6.0
    assert path == ["P", "Q", "R", "S"]

def test_equal_cost_paths_returns_first_found():
    # Two paths of equal cost: S->A->T (cost 5+5=10) and S->B->T (cost 3+7=10)
    # Should return whichever path the algorithm discovers first (heap order)
    g = {
        "S": {"A": 5.0, "B": 3.0},
        "A": {"T": 5.0},
        "B": {"T": 7.0},
        "T": {}
    }
    dist, path = dijkstra(g, "S", "T")
    assert dist == 10.0
    assert path == ["S", "B", "T"]  # B is reached first (cost 3 < 5)
```

Can you implement `dijkstra` to make all the tests pass?

I'm implementing a small URL router for a web framework and need help writing this function. Here are the tests:

```python
import re
from typing import Optional, Dict

def match_route(pattern: str, path: str) -> Optional[Dict[str, str]]:
    """Match a URL path against a route pattern and extract path parameters.

    Route patterns may include named segments like `{name}` which match
    a single path segment (no slashes). If the path matches the pattern,
    returns a dict of extracted parameters. If it does not match, returns None.

    Matching is case-insensitive for the static (non-parameter) parts.

    Args:
        pattern: A route pattern string, e.g. '/users/{id}/posts/{post_id}'
        path: The incoming URL path to match.

    Returns:
        Dict of captured parameters if matched, empty dict if matched with no
        params, or None if no match.
    """
    pass


def test_simple_match_no_params():
    result = match_route('/home', '/home')
    assert result == {}

def test_no_match_returns_none():
    result = match_route('/about', '/contact')
    assert result is None

def test_single_param_extraction():
    result = match_route('/users/{id}', '/users/42')
    assert result == {'id': '42'}

def test_multiple_param_extraction():
    result = match_route('/users/{user_id}/posts/{post_id}', '/users/7/posts/99')
    assert result == {'user_id': '7', 'post_id': '99'}

def test_static_parts_case_insensitive():
    # Static segments should match case-insensitively
    result = match_route('/Users/{id}', '/users/123')
    assert result == {'id': '123'}

def test_param_values_preserve_case():
    # Parameter values should preserve original case
    result = match_route('/files/{filename}', '/files/Report.pdf')
    assert result == {'filename': 'Report.pdf'}

def test_trailing_slash_sensitive():
    # Trailing slash makes it a different route - should NOT match
    result = match_route('/home', '/home/')
    assert result is None

def test_trailing_slash_insensitive():
    # Trailing slashes should be ignored during matching
    result = match_route('/home', '/home/')
    assert result == {}

def test_path_with_param_no_match_extra_segment():
    # Extra segments should not match
    result = match_route('/users/{id}', '/users/42/extra')
    assert result is None
```

Can you implement `match_route` to make all these tests pass?

